const solicitud = $('When Executed by Another Workflow').first().json;
const eventos = $input.all();

const profesionales = ['Martin', 'Lucas', 'Nicolas'];

const normalizar = (valor) =>
  String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const solicitado = normalizar(solicitud.profesional);
const sinPreferencia = solicitado === 'sin_preferencia';

const duracion = Number(solicitud.duracion_minutos);

const inicio = DateTime.fromISO(
  `${solicitud.fecha}T${solicitud.hora}`,
  { zone: 'America/Argentina/Buenos_Aires' }
);

if (!solicitado) {
  throw new Error('Falta el profesional');
}

if (!sinPreferencia &&
    !profesionales.some(p => normalizar(p) === solicitado)) {
  throw new Error('Profesional no reconocido');
}

if (!inicio.isValid) {
  throw new Error('Fecha u hora inválida');
}

if (!Number.isFinite(duracion) || duracion <= 0) {
  throw new Error('Duración inválida');
}

const fin = inicio.plus({ minutes: duracion });
const ocupados = new Set();
const conflictos = [];

for (const item of eventos) {
  const evento = item.json;

  if (!evento.id || !evento.summary) continue;
  if (evento.status === 'cancelled') continue;

  const partes = evento.summary.split(' - ');
  const profesionalEvento = normalizar(partes.at(-1))
    .split(',')[0]
    .trim();

  const desdeISO = evento.start?.dateTime;
  const hastaISO = evento.end?.dateTime;

  if (!desdeISO || !hastaISO) {
    throw new Error(`Evento sin horario válido: ${evento.id}`);
  }

  const desde = DateTime.fromISO(desdeISO);
  const hasta = DateTime.fromISO(hastaISO);

  if (!desde.isValid || !hasta.isValid) {
    throw new Error(`Fechas inválidas en evento: ${evento.id}`);
  }

  if (desde < fin && hasta > inicio) {
    const reconocido = profesionales.some(
      p => normalizar(p) === profesionalEvento
    );

    if (!reconocido) {
      throw new Error(
        `Profesional desconocido en evento: ${evento.id}`
      );
    }

    ocupados.add(profesionalEvento);

    if (sinPreferencia || profesionalEvento === solicitado) {
      conflictos.push({
        id: evento.id,
        titulo: evento.summary,
        inicio: desdeISO,
        fin: hastaISO
      });
    }
  }
}

const candidatos = sinPreferencia
  ? profesionales
  : profesionales.filter(p => normalizar(p) === solicitado);

const disponibles = candidatos.filter(
  p => !ocupados.has(normalizar(p))
);

const asignado = disponibles[0] ?? null;
const disponible = asignado !== null;

return [{
  json: {
    request_id: solicitud.request_id,
    profesional: asignado,
    profesional_solicitado: solicitud.profesional,
    profesionales_disponibles: disponibles,
    fecha: solicitud.fecha,
    hora: solicitud.hora,
    duracion_minutos: duracion,
    disponible,
    conflictos,
    estado: disponible ? 'disponible' : 'no_disponible'
  }
}];

const solicitud = $('When Executed by Another Workflow')
  .first().json;

const error = $input.first()?.json ?? {};

return [{
  json: {
    request_id: solicitud.request_id,
    profesional: solicitud.profesional,
    fecha: solicitud.fecha,
    hora: solicitud.hora,
    duracion_minutos: solicitud.duracion_minutos,
    disponible: false,
    estado: "error_tecnico",
    error_codigo: "CALENDAR_UNAVAILABLE",
    reserva_confirmada: false,
    conflictos: [],
    mensaje: "No pudimos verificar la agenda en este momento. Por favor, intentá nuevamente.",
    error_detalle: String(
      error.error?.message ??
      error.message ??
      "Error desconocido"
    )
  }
}];
